SELECT 'gongkao', '先合作后单干', 'kp-eng-c-mix-work', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "先合作后单干"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "分段剥离法。总工程量 = 合作完成的量 + 剩下的量。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "经典句式：“甲乙先合作了 n 天，然后甲被调走，剩下的由乙独自完成”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "画线段图，把工程明确切分为两个阶段。分别计算每个阶段消耗了多少工程量。"}]}, {"type": "katexBlock", "attrs": {"content": "W_{剩余} = W_{总} - (P_A + P_B) \\times T_{合作}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[赋总量, 出效率] --> B[计算第一阶段(合作)完成的工作量]\nB --> C[用总工程量减去已完成量, 得出剩余工程量]\nC --> D[剩余工程量 / 留守者的单干效率 = 剩下需要的天数]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 甲需 10 天，乙需 15 天。两人合作 3 天后，甲去其他工地，剩下由乙做。乙还需要几天？选项：A. 5  B. 6  C. 7.5  D. 9"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋总量：10 和 15 的公倍数 W = 30。P甲 = 3，P乙 = 2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "合作阶段：P合 = 5。合作 3 天，干了 5 × 3 = 15 的活。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算剩余：剩下 W余 = 30 - 15 = 15。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "单干阶段：乙单干，T = 15 ÷ 2 = 7.5 天。选 C。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看错问题：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "题目最后问的是“乙还需要几天”还是“一共花了几天”？如果是前者，答案是 7.5；如果是后者，答案是 3 + 7.5 = 10.5。考场上一定要把最后半句话用红笔圈起来！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "无论题目怎么花里胡哨（甲走乙留，乙走丙来），只要牢记“干了多少减多少，谁在场就除以谁的效率”。"}]}]}$$ AS jsonb), NULL, '先合作后单干的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "先合作后单干"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_c_mix_work", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
